=== calibration-single-source.mjs ===
// The px -> um scale of every figure comes from ONE measured table: UM_PER_BAR
// and SCALEBAR_PX in analysis/measure_vessels.py. annotate_overlays.py reads them
// by importing from there, never by carrying its own copy — that is the invariant
// this check holds.
//
// Companion to scale-numbers-match-calibration, which holds the numbers quoted in
// *markdown* to that table. Markdown is all that check reads, so a second table
// defined in Python is invisible to it: the two rules cover opposite halves of the
// same single-source line.
//
// Parse rather than grep: the names are stripped of comments and of every string
// literal (including the docstrings that spell the table out) first, and only an
// assignment — `NAME =`, or an annotated `NAME: dict =` — counts. A docstring
// quoting "SCALEBAR_PX = {'fig1': 61}" documents the table; it does not define it.
const SOURCE = 'analysis/measure_vessels.py';
const SHARED = '.claudinite/shared/';        // read-only mounted canon
const CALIBRATION = ['UM_PER_BAR', 'SCALEBAR_PX'];
const ASSIGN = new RegExp(`^\\s*(${CALIBRATION.join('|')})\\s*(?::[^=\\n]+)?=(?!=)`);

// Blank out comments and string literals, keeping every newline and every column
// so line numbers and the assignment shape survive. Handles ''' / """ blocks,
// single-quoted strings and escapes; a `#` inside a string is not a comment.
function code(text) {
  const out = [];
  let i = 0;
  let quote = null;                          // the open delimiter, or null
  while (i < text.length) {
    const c = text[i];
    if (quote) {
      if (c === '\\' && quote.length === 1) { out.push(' ', ' '); i += 2; continue; }
      if (text.startsWith(quote, i)) {
        out.push(' '.repeat(quote.length));
        i += quote.length;
        quote = null;
        continue;
      }
      out.push(c === '\n' ? '\n' : ' ');
      i += 1;
      continue;
    }
    if (c === '#') {                         // to end of line
      while (i < text.length && text[i] !== '\n') { out.push(' '); i += 1; }
      continue;
    }
    if (c === '"' || c === "'") {
      quote = text.startsWith(c.repeat(3), i) ? c.repeat(3) : c;
      out.push(' '.repeat(quote.length));
      i += quote.length;
      continue;
    }
    out.push(c);
    i += 1;
  }
  return out.join('');
}

// Every line of `text` that assigns one of the calibration names, as { name, line }.
// Only statements count: a line that starts inside an open bracket is a continuation,
// where `UM_PER_BAR=50` is a keyword argument being passed, not the table being defined.
function definitions(text) {
  const out = [];
  let depth = 0;
  code(text).split('\n').forEach((line, i) => {
    const hit = depth === 0 ? ASSIGN.exec(line) : null;
    if (hit) out.push({ name: hit[1], line: i + 1 });
    for (const c of line) {
      if ('([{'.includes(c)) depth += 1;
      else if (')]}'.includes(c)) depth = Math.max(0, depth - 1);
    }
  });
  return out;
}

const rule = {
  id: 'calibration-single-source',
  severity: 'blocking',
  description: 'The scale-bar calibration is defined only in the extraction script',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'UM_PER_BAR / SCALEBAR_PX are a measurement, not a constant — a second definition means two calibrations, and the one a given script happens to read wins silently, re-labelling its lengths and densities with a scale nobody re-measured',

  run(ctx) {
    const out = [];
    const flag = (file, line, what, fix) => out.push({
      rule: rule.id, severity: rule.severity, file, line, what, why: rule.why, fix, doc: rule.doc,
    });

    for (const file of ctx.tracked) {
      if (!file.endsWith('.py') || file.startsWith(SHARED)) continue;
      const text = ctx.read(file);
      if (text === null) continue;
      const defs = definitions(text);

      if (file === SOURCE) {
        // The source file itself: a name assigned twice is the same drift, one
        // file in. The later assignment wins and the earlier measurement is dead
        // code that still reads as the calibration.
        for (const name of CALIBRATION) {
          const mine = defs.filter((d) => d.name === name);
          if (mine.length < 2) continue;
          flag(file, mine[mine.length - 1].line,
            `${name} is assigned ${mine.length} times in ${SOURCE} (lines ${mine.map((d) => d.line).join(', ')})`,
            `keep one ${name} assignment — delete the copies, or if the bar was re-measured, replace the single definition with the new value`);
        }
        continue;
      }

      for (const def of defs) {
        flag(file, def.line,
          `${file} defines its own ${def.name}`,
          `import it instead — \`from measure_vessels import ${def.name}\`, the way the overlay script already reads the table; if a bar really was re-measured, change the value in ${SOURCE}, the one place it is measured`);
      }
    }
    return out;
  },
};

export default rule;

=== locked-metric-fields.mjs ===
// The extraction script is the single place the three locked metrics are
// computed and named; every downstream table, overlay banner and results
// markdown quotes those field names back.
const MEASURE = 'analysis/measure_vessels.py';

// The professor's three asks, and the metric fields each one is locked to.
const LOCKED = [
  { ask: 'COUNT', meaning: 'branch segments (junction-to-junction / junction-to-tip)', fields: ['segments'] },
  { ask: 'CATEGORIZE', meaning: 'caliber - capillary vs penetrating artery by centerline diameter', fields: ['capillary', 'artery'] },
  { ask: 'MEASURE', meaning: 'total centerline length, as raw um and as density', fields: ['length_um', 'length_density'] },
];

// Parse rather than grep: the metric names count only where they are built as
// keyword fields of a dict(...) construction, never where prose, a docstring or
// a print format string happens to mention them. `defaultdict(` is not a dict
// construction here, hence the non-word/non-dot lookbehind.
const DICT = /(?<![\w.])dict\s*\(/g;
const KWARG = /(?:^|[(,]\s*)([A-Za-z_]\w*)\s*=(?!=)/g;

// The real metrics dict carries trailing `#` comments between its fields, which
// would otherwise sit between a field and the comma that anchors the next one.
// Blank them (keeping the newline) rather than the whole line, so line numbers
// still count. Quote-aware: a `#` inside a string literal is not a comment.
function stripComments(text) {
  return text.split('\n').map((line) => {
    let quote = null;
    for (let i = 0; i < line.length; i += 1) {
      const c = line[i];
      if (quote) {
        if (c === '\\') i += 1;
        else if (c === quote) quote = null;
      } else if (c === '"' || c === "'") quote = c;
      else if (c === '#') return line.slice(0, i);
    }
    return line;
  }).join('\n');
}

// The fields of every dict(...) built in the script, with the line the first
// dict carrying a locked field starts on (where a reviewer should look).
function reportedFields(source) {
  const text = stripComments(source);
  const fields = new Set();
  let dicts = 0;
  let line = null;
  for (const m of text.matchAll(DICT)) {
    dicts += 1;
    let depth = 0;
    let end = m.index + m[0].length - 1;
    for (; end < text.length; end += 1) {
      if (text[end] === '(') depth += 1;
      else if (text[end] === ')' && (depth -= 1) === 0) break;
    }
    const body = text.slice(m.index, end + 1);
    const here = [...body.matchAll(KWARG)].map((k) => k[1]);
    if (line === null && here.some((f) => LOCKED.some((l) => l.fields.includes(f)))) {
      line = text.slice(0, m.index).split('\n').length;
    }
    here.forEach((f) => fields.add(f));
  }
  return { fields, dicts, line };
}

const rule = {
  id: 'locked-metric-fields',
  severity: 'blocking',
  description: 'The extraction script still reports all three locked metrics',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'COUNT / CATEGORIZE / MEASURE are locked definitions - dropping or renaming one of their fields changes what every recorded number means, and it fails silently: the metric just stops appearing in the tables it used to anchor',

  run(ctx) {
    const text = ctx.read(MEASURE);
    if (text === null) return [];
    const { fields, dicts, line } = reportedFields(text);
    if (dicts === 0) {
      return [{
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line: null,
        what: 'no metrics dict found in the extraction script',
        why: rule.why,
        fix: 'keep the per-panel metrics built as a dict(field=...) in this file - it is the one place the locked metric names are defined',
        doc: rule.doc,
      }];
    }
    return LOCKED
      .map((lock) => ({ lock, missing: lock.fields.filter((f) => !fields.has(f)) }))
      .filter(({ missing }) => missing.length)
      .map(({ lock, missing }) => ({
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line,
        what: `${lock.ask} is locked to ${lock.meaning}, but the metrics dict reports no ${missing.join(' / ')} field`,
        why: rule.why,
        fix: `report ${missing.join(' and ')} again from the metrics dict; if the definition of ${lock.ask} really is changing, that is an owner decision - unlock it in the pack RULES.md first, then re-record every number that was measured under the old definition`,
        doc: rule.doc,
      }));
  },
};

export default rule;

=== overlay-color-contrast.mjs ===
// The presentation overlay script — the one whose output the owner looks at.
// The 3-panel debug view in measure_vessels.py is deliberately NOT in scope: it
// dims the original and uses red for arteries, which is fine for a QA render and
// wrong for the presentation figure.
const PRESENTATION = 'analysis/annotate_overlays.py';

// An (r, g, b) or (r, g, b, a) literal — the only way a drawn colour is spelled
// in this script (PIL fill=/np.array colours).
const TUPLE = /\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*(?:,\s*\d{1,3}\s*)?\)/g;

// Red-dominant = bright red channel that clearly beats BOTH others. Magenta
// (255, 0, 255) and the yellow label colour (255, 235, 60) stay legal: they read
// against the red signal because blue resp. green carries them.
const MARGIN = 60;
const isRedDominant = (r, g, b) => r >= 128 && r - g >= MARGIN && r - b >= MARGIN;

const rule = {
  id: 'overlay-color-contrast',
  severity: 'blocking',
  description: 'Presentation overlay marks must not be red-dominant',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'the gP-CD31 signal being measured IS red — a red outline, arrow or ring vanishes on the very vessels it is supposed to mark',

  run(ctx) {
    const text = ctx.read(PRESENTATION);
    if (text === null) return [];
    const out = [];
    text.split('\n').forEach((line, i) => {
      // A comment or a docstring line describes a colour, it doesn't draw one.
      if (line.trim().startsWith('#')) return;
      for (const m of line.matchAll(TUPLE)) {
        const [r, g, b] = [m[1], m[2], m[3]].map(Number);
        if (!isRedDominant(r, g, b)) continue;
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file: PRESENTATION,
          line: i + 1,
          what: `overlay colour (${r}, ${g}, ${b}) is red-dominant`,
          why: rule.why,
          fix: 'pick a colour that contrasts with the red channel — cyan for capillaries, green for arteries, magenta for junctions, yellow for labels (see the pack RULES.md)',
          doc: rule.doc,
        });
      }
    });
    return out;
  },
};

export default rule;

